BEGIN;
ALTER TABLE public.maintenance_orders ADD COLUMN prazo_entrega_dias integer CHECK(prazo_entrega_dias BETWEEN 1 AND 3650),ADD COLUMN prazo_base_aprovacao_em timestamptz;
-- The expected repair interval is separate from measured workshop SLA.
DO $upgrade$ DECLARE def text;BEGIN
 SELECT pg_get_functiondef('maintenance_private.registration_profile(jsonb,boolean)'::regprocedure) INTO def;
 def:=replace(def,']$fields$::jsonb',',["prazo_entrega_dias","Prazo médio para concluir após aprovação (dias corridos)","number",1,3650]]$fields$::jsonb');def:=replace(def,'''equipe_tecnica'',''garantia_dias'']','''equipe_tecnica'',''garantia_dias'',''prazo_entrega_dias'']');EXECUTE def;
 SELECT pg_get_functiondef('maintenance_private.order_command(uuid,text,jsonb)'::regprocedure) INTO def;
 def:=replace(def,'km_abertura,previsao_entrega)','km_abertura,previsao_entrega,prazo_entrega_dias)');
 def:=replace(def,'km,nullif(payload->>''previsao_entrega'','''')::timestamptz)','km,nullif(payload->>''previsao_entrega'','''')::timestamptz,coalesce(nullif(payload->>''prazo_entrega_dias'','''')::integer,nullif(partner.onboarding_profile->>''prazo_entrega_dias'','''')::integer))');
 def:=replace(def,'SET orcamento_status=payload->>''decisao''','SET prazo_entrega_dias=coalesce(nullif(payload->>''prazo_entrega_dias'','''')::integer,o.prazo_entrega_dias),orcamento_status=payload->>''decisao''');
 def:=replace(def,'SET diagnostico=nullif','SET prazo_entrega_dias=CASE WHEN payload ? ''prazo_entrega_dias'' THEN nullif(payload->>''prazo_entrega_dias'','''')::integer ELSE o.prazo_entrega_dias END,diagnostico=nullif');EXECUTE def;
END $upgrade$;
CREATE FUNCTION maintenance_private.order_deadline() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 IF NEW.orcamento_status='aprovado' THEN
 IF TG_OP='INSERT' OR NEW.aprovado_em IS DISTINCT FROM OLD.aprovado_em OR NEW.orcamento_status IS DISTINCT FROM OLD.orcamento_status OR NEW.prazo_entrega_dias IS DISTINCT FROM OLD.prazo_entrega_dias THEN
 IF NEW.prazo_entrega_dias IS NULL THEN RAISE EXCEPTION 'Informe o prazo de entrega em dias corridos após aprovação.';END IF;END IF;
 IF NEW.prazo_entrega_dias IS NOT NULL THEN NEW.prazo_base_aprovacao_em:=NEW.aprovado_em;NEW.previsao_entrega:=((NEW.aprovado_em AT TIME ZONE 'America/Sao_Paulo')+make_interval(days=>NEW.prazo_entrega_dias)) AT TIME ZONE 'America/Sao_Paulo';END IF;
 ELSIF TG_OP='UPDATE' AND OLD.prazo_base_aprovacao_em IS NOT NULL THEN NEW.prazo_base_aprovacao_em:=NULL;NEW.previsao_entrega:=NULL;
 END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION maintenance_private.order_deadline() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_order_deadline BEFORE INSERT OR UPDATE ON public.maintenance_orders FOR EACH ROW EXECUTE FUNCTION maintenance_private.order_deadline();
CREATE TABLE public.maintenance_order_dispatches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,order_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('abertura','aprovacao')),event_key text NOT NULL,approval_at timestamptz,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','accepted','failed','unknown','unavailable','obsolete')),snapshot jsonb NOT NULL,phone text,attempts integer NOT NULL DEFAULT 0,claim_token uuid,claimed_at timestamptz,provider_message_id text,error_message text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,event_key),FOREIGN KEY(order_id,company_id) REFERENCES public.maintenance_orders(id,company_id));
ALTER TABLE public.maintenance_order_dispatches ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.maintenance_order_dispatches FROM PUBLIC,anon,authenticated;GRANT SELECT(id,company_id,order_id,kind,status,attempts,claimed_at,provider_message_id,error_message,created_at,updated_at) ON public.maintenance_order_dispatches TO authenticated;GRANT ALL ON public.maintenance_order_dispatches TO service_role;
CREATE INDEX dispatch_company_order ON public.maintenance_order_dispatches(company_id,order_id,created_at DESC);
CREATE POLICY dispatch_read ON public.maintenance_order_dispatches TO authenticated USING(maintenance_private.partner_access(company_id));
CREATE FUNCTION maintenance_private.order_document(c uuid,target uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE o public.maintenance_orders;v public.veiculos;p public.maintenance_partners;co public.companies;items jsonb;BEGIN
 IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Sem acesso à empresa.' USING ERRCODE='42501';END IF;
 SELECT * INTO o FROM public.maintenance_orders WHERE id=target AND company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE='42501';END IF;
 SELECT * INTO v FROM public.veiculos WHERE id=o.vehicle_id AND company_id=c;SELECT * INTO p FROM public.maintenance_partners WHERE id=o.partner_id AND company_id=c;SELECT * INTO co FROM public.companies WHERE id=c;
 SELECT coalesce(jsonb_agg(jsonb_build_object('tipo',i.tipo,'descricao',i.descricao,'quantidade',i.quantidade,'valor_unitario',i.valor_unitario) ORDER BY i.created_at,i.id),'[]') INTO items FROM public.maintenance_order_items i WHERE company_id=c AND order_id=o.id;
 RETURN jsonb_build_object('company',jsonb_build_object('nome',co.nome),'order',jsonb_build_object('numero',o.numero,'tipo',o.tipo,'prioridade',o.prioridade,'status',o.status,'descricao_problema',o.descricao_problema,'diagnostico',o.diagnostico,'data_abertura',o.data_abertura,'km_abertura',o.km_abertura,'km_entrada',o.km_entrada,'prazo_entrega_dias',o.prazo_entrega_dias,'aprovado_em',o.prazo_base_aprovacao_em,'previsao_entrega',o.previsao_entrega,'orcamento_status',o.orcamento_status,'valor_total',o.valor_total),'vehicle',jsonb_build_object('placa',v.placa,'marca_modelo',v.marca_modelo,'tipo',v.tipo,'ano_fabricacao',v.ano_fabricacao,'ano_modelo',v.ano_modelo,'chassi',v.chassi,'renavam',v.renavam,'combustivel',v.combustivel,'capacidade_peso_ton',v.capacidade_peso_ton,'capacidade_volume_m3',v.capacidade_volume_m3,'tipo_carga',v.tipo_carga,'km_atual',v.km_atual),'partner',jsonb_build_object('nome',coalesce(p.nome_fantasia,p.razao_social),'cnpj_cpf',p.cnpj_cpf,'contato_nome',p.contato_nome,'telefone',p.telefone,'whatsapp',p.whatsapp,'email',p.email,'endereco',concat_ws(', ',p.logradouro,p.numero,p.bairro,p.cidade,p.estado,p.cep)),'items',items);END $$;
REVOKE ALL ON FUNCTION maintenance_private.order_document(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.order_document(uuid,uuid) TO authenticated;
CREATE FUNCTION maintenance_private.queue_order_dispatch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE k text;BEGIN
 IF TG_OP='INSERT' THEN k:='abertura';ELSIF NEW.orcamento_status='aprovado' AND NEW.aprovado_em IS DISTINCT FROM OLD.aprovado_em THEN k:='aprovacao';END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.prazo_entrega_dias,NEW.previsao_entrega,NEW.prazo_base_aprovacao_em) IS DISTINCT FROM ROW(OLD.prazo_entrega_dias,OLD.previsao_entrega,OLD.prazo_base_aprovacao_em) THEN PERFORM maintenance_private.order_event(NEW.company_id,NEW.id,'comentario','Previsão após aprovação atualizada',jsonb_build_object('dias_corridos',NEW.prazo_entrega_dias,'aprovacao_em',NEW.prazo_base_aprovacao_em,'previsao_entrega',NEW.previsao_entrega));END IF;
 IF k IS NOT NULL AND auth.uid() IS NOT NULL THEN INSERT INTO public.maintenance_order_dispatches(company_id,order_id,kind,event_key,approval_at,snapshot) VALUES(NEW.company_id,NEW.id,k,CASE WHEN k='abertura' THEN 'abertura' ELSE 'aprovacao:'||NEW.aprovado_em::text END,CASE WHEN k='aprovacao' THEN NEW.aprovado_em END,maintenance_private.order_document(NEW.company_id,NEW.id)) ON CONFLICT(order_id,event_key) DO NOTHING;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION maintenance_private.queue_order_dispatch() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER queue_order_dispatch AFTER INSERT OR UPDATE ON public.maintenance_orders FOR EACH ROW EXECUTE FUNCTION maintenance_private.queue_order_dispatch();
CREATE FUNCTION maintenance_private.order_dispatch_command(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE actor uuid:=auth.uid();d public.maintenance_order_dispatches;o public.maintenance_orders;p public.maintenance_partners;recipient_phone text;outcome text;message_id text;BEGIN
 IF actor IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Sem acesso à empresa.' USING ERRCODE='42501';END IF;
 SELECT * INTO o FROM public.maintenance_orders WHERE id=(b->>'id')::uuid AND company_id=c FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE='42501';END IF;
 IF action='document' THEN RETURN maintenance_private.order_document(c,o.id);END IF;
 IF action NOT IN ('claim','finish') OR b->>'kind' NOT IN ('abertura','aprovacao') THEN RAISE EXCEPTION 'Operação inválida.';END IF;
 SELECT * INTO d FROM public.maintenance_order_dispatches WHERE company_id=c AND order_id=o.id AND kind=b->>'kind' ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Não há envio registrado para esta etapa da OS.';END IF;
 IF action='claim' THEN
 IF d.status='accepted' THEN RETURN jsonb_build_object('status','accepted');END IF;
 IF o.status IN ('cancelada','encerrada') OR (d.kind='aprovacao' AND (o.orcamento_status<>'aprovado' OR o.aprovado_em IS DISTINCT FROM d.approval_at)) THEN UPDATE public.maintenance_order_dispatches SET status='obsolete' WHERE id=d.id;RETURN jsonb_build_object('status','obsolete');END IF;
 IF d.status='sending' AND d.claimed_at>clock_timestamp()-interval '5 minutes' THEN RETURN jsonb_build_object('status','sending');END IF;
 IF d.status IN ('unknown','sending') AND b->'confirm_uncertain' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Confira o WhatsApp antes de repetir: o envio pode ter sido recebido.';END IF;
 SELECT * INTO p FROM public.maintenance_partners WHERE id=o.partner_id AND company_id=c AND status='ativo';IF NOT FOUND THEN RAISE EXCEPTION 'Oficina indisponível.';END IF;
 recipient_phone:=regexp_replace(coalesce(nullif(p.whatsapp,''),p.telefone,''),'[^0-9]','','g');IF recipient_phone ~ '^[1-9][0-9][2-9][0-9]{7,8}$' THEN recipient_phone:='55'||recipient_phone;END IF;
 IF recipient_phone !~ '^55[1-9][0-9][2-9][0-9]{7,8}$' THEN UPDATE public.maintenance_order_dispatches SET status='unavailable',error_message='Cadastre um WhatsApp válido na oficina.' WHERE id=d.id;RETURN jsonb_build_object('status','unavailable','error','Cadastre um WhatsApp válido na oficina.');END IF;
 UPDATE public.maintenance_order_dispatches SET phone=recipient_phone,status='sending',claim_token=gen_random_uuid(),claimed_at=clock_timestamp(),attempts=attempts+1,updated_at=clock_timestamp(),snapshot=maintenance_private.order_document(c,o.id) WHERE id=d.id RETURNING * INTO d;
 PERFORM maintenance_private.order_event(c,o.id,'comentario','Envio de Excel à oficina iniciado',jsonb_build_object('envio',d.id,'etapa',d.kind,'tentativa',d.attempts));
 RETURN jsonb_build_object('status','claimed','token',d.claim_token,'dispatch_id',d.id,'phone',d.phone,'snapshot',d.snapshot);END IF;
 IF d.status<>'sending' OR d.claim_token IS DISTINCT FROM (b->>'token')::uuid THEN RAISE EXCEPTION 'Tentativa expirada.' USING ERRCODE='40001';END IF;
 outcome:=b->>'status';message_id:=nullif(b->>'message_id','');IF outcome IS NULL OR outcome NOT IN ('accepted','failed','unknown') OR length(message_id)>200 OR (outcome='accepted' AND message_id IS NULL) THEN RAISE EXCEPTION 'Resultado inválido.';END IF;
 UPDATE public.maintenance_order_dispatches SET status=outcome,provider_message_id=message_id,error_message=CASE outcome WHEN 'accepted' THEN NULL WHEN 'failed' THEN 'Não foi possível enviar o Excel. Confira a Evolution API e o contato da oficina.' ELSE 'Envio incerto. Confira o WhatsApp antes de repetir.' END,claim_token=NULL,updated_at=clock_timestamp() WHERE id=d.id RETURNING * INTO d;
 IF outcome='accepted' THEN INSERT INTO public.maintenance_messages(company_id,order_id,partner_id,direcao,canal,conteudo,assunto,destinatario,enviado_por,created_by,situacao,efetivada_em,request_id) VALUES(c,o.id,o.partner_id,'enviada','whatsapp',format(E'Excel da OS %s aceito pela Evolution API.\nVeículo: %s · %s\nPrazo após aprovação: %s dias corridos.\nPrevisão: %s',o.numero,d.snapshot->'vehicle'->>'placa',d.snapshot->'vehicle'->>'marca_modelo',coalesce(o.prazo_entrega_dias::text,'a definir'),coalesce(to_char(o.previsao_entrega AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),'aguardando aprovação')),'Excel da OS '||o.numero,d.phone,actor,actor,'confirmada',clock_timestamp(),d.id) ON CONFLICT(company_id,request_id) WHERE request_id IS NOT NULL DO NOTHING;END IF;
 PERFORM maintenance_private.order_event(c,o.id,'comentario',CASE outcome WHEN 'accepted' THEN 'Excel e mensagem aceitos pela Evolution API' WHEN 'failed' THEN 'Falha no envio de Excel à oficina' ELSE 'Envio de Excel com resultado incerto' END,jsonb_build_object('envio',d.id,'etapa',d.kind,'provider_message_id',d.provider_message_id,'destinatario',d.phone,'previsao_entrega',d.snapshot->'order'->'previsao_entrega'));
 RETURN jsonb_build_object('status',d.status,'error',d.error_message);END $$;
REVOKE ALL ON FUNCTION maintenance_private.order_dispatch_command(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.order_dispatch_command(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.maintenance_order_dispatch(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.order_dispatch_command(target_company,command,body);$$;
REVOKE ALL ON FUNCTION public.maintenance_order_dispatch(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.maintenance_order_dispatch(uuid,text,jsonb) TO authenticated;
COMMIT;
